package device

import "github.com/google/uuid"

// GUID identifies the device externally (e.g. to a controller or, later,
// firmware/MQTT) and is generated by the database; it never changes and is
// never client-settable, unlike ID which is only an internal join key.
type Device struct {
	ID            int64
	GUID          uuid.UUID `gorm:"column:guid;type:uuid;default:gen_random_uuid()"`
	EnvironmentID int64     `gorm:"column:environment_id"`
	DeviceType    int       `gorm:"column:device_type"`
	Name          string
	PositionX     float64 `gorm:"column:position_x"`
	PositionY     float64 `gorm:"column:position_y"`
	Rotation      float64
}

type DeviceSaveDTO struct {
	ID            int64
	EnvironmentID int64
	DeviceType    int
	Name          string
	PositionX     float64
	PositionY     float64
	Rotation      float64
}
